-- ShaktiKram built-in exercise catalogue: 144 exercises, 419 exercise-muscle links.
-- File: backend/supabase/seed_exercise_catalogue.sql
--
-- WHAT THIS DOES
--   * Fills in category, equipment and notes on the two existing seed exercises (Bench press, Lat pulldown) WITHOUT changing their ids.
--     Only fields that are still empty are filled; anything you edited is kept.
--   * Inserts the catalogue exercises as built-in rows (is_custom = false) with stable ids: md5('catalogue:exercise:' || key)::uuid.
--   * Inserts exercise_muscles links (one primary per exercise, plus secondaries) with stable ids.
--   * Uses only existing muscles and equipment (looked up by key). Creates no reference rows.
--
-- SAFE TO RE-RUN
--   * Never deletes, truncates, or resets anything. Never touches custom exercises (is_custom = true).
--   * An exercise whose name already exists (any case, not deleted) is skipped, not duplicated and not overwritten.
--     That includes an exercise you created yourself with the same name; the skipped names are listed in a NOTICE.
--   * A link is added only when that exercise/muscle pair has no live link, and a second primary is never added.
--     Links you removed are not brought back (their stable ids already exist).
--   * Everything runs in one transaction. Any problem aborts it and nothing is written.
--
-- RUN IN: Supabase SQL Editor (runs as the postgres role). The last statement is a one-table check summary.
-- Run the dev/test seed or reference seed first if the muscle and equipment tables are empty; the checks below stop early if they are.

begin;

-- 0. Preflight: stop before writing anything if the reference data or schema is not as expected.
do $preflight$
declare v_missing text;
begin
  select string_agg(k, ', ') into v_missing from unnest(array['abductors', 'adductors', 'biceps', 'brachialis', 'calves', 'external_obliques', 'forearms', 'front_delts', 'glutes', 'hamstrings', 'internal_obliques', 'lats', 'lower_abs', 'lower_chest', 'lower_traps', 'middle_chest', 'middle_traps', 'quadriceps', 'rear_delts', 'rhomboids', 'side_delts', 'spinal_erectors', 'transverse_abdominis', 'triceps_lateral_head', 'triceps_long_head', 'triceps_medial_head', 'upper_abs', 'upper_chest', 'upper_traps']) k
   where not exists (select 1 from muscles m where m.key = k and m.deleted_at is null);
  if v_missing is not null then raise exception 'preflight failed: muscles missing: %', v_missing; end if;
  select string_agg(k, ', ') into v_missing from unnest(array['assisted_pullup_machine', 'barbell', 'bodyweight', 'cable_machine', 'calf_raise_machine', 'chest_press_machine', 'dip_station', 'dumbbell', 'ez_bar', 'flat_bench', 'kettlebell', 'lat_pulldown_machine', 'leg_curl_machine', 'leg_extension_machine', 'leg_press_machine', 'pec_deck_machine', 'pull_up_bar', 'resistance_bands', 'seated_row_machine', 'shoulder_press_machine', 'smith_machine']) k
   where not exists (select 1 from equipment q where q.key = k and q.deleted_at is null);
  if v_missing is not null then raise exception 'preflight failed: equipment missing: %', v_missing; end if;
  if not exists (select 1 from information_schema.columns where table_name = 'exercises' and column_name in ('category', 'equipment_id', 'notes', 'removed_on') having count(*) = 4) then
    raise exception 'preflight failed: exercises table is missing Stage 2 columns';
  end if;
end $preflight$;

-- 1. The catalogue, as data. Nothing is written yet.
create temporary table _cat_ex (key text primary key, name text not null, category text not null, equipment_key text not null, notes text not null) on commit drop;

create temporary table _cat_link (exercise_key text not null, muscle_key text not null, role text not null, primary key (exercise_key, muscle_key)) on commit drop;

-- The two exercises that already exist keep their ids.
create temporary table _cat_seed (key text primary key, id uuid not null) on commit drop;

-- Final id for every catalogue exercise.
create temporary table _cat_id on commit drop as
  select c.key, coalesce(s.id, md5('catalogue:exercise:' || c.key)::uuid) as id from _cat_ex c left join _cat_seed s using (key);

-- 2. Fill empty fields on the two existing seed exercises (keeps your edits).
update exercises e
   set category = coalesce(e.category, c.category),
       equipment_id = coalesce(e.equipment_id, (select q.id from equipment q where q.key = c.equipment_key and q.deleted_at is null)),
       notes = coalesce(e.notes, c.notes)
  from _cat_seed s
  join _cat_ex c on c.key = s.key
 where e.id = s.id and e.deleted_at is null and e.is_custom = false
   and (e.category is null or e.equipment_id is null or e.notes is null);

-- 3. Insert catalogue exercises. Existing names (live, any case) and existing ids are skipped.
do $skipped$
declare v_names text;
begin
  select string_agg(c.name, ', ' order by c.name) into v_names
    from _cat_ex c join _cat_id i using (key)
   where exists (select 1 from exercises e where lower(e.name) = lower(c.name) and e.deleted_at is null and e.id <> i.id);
  if v_names is not null then raise notice 'Skipped (a different exercise with this name already exists): %', v_names; end if;
end $skipped$;

select i.id, c.name, false, c.category, (select q.id from equipment q where q.key = c.equipment_key and q.deleted_at is null), c.notes
  from _cat_ex c join _cat_id i using (key)
 where not exists (select 1 from exercises e where lower(e.name) = lower(c.name) and e.deleted_at is null)
on conflict do nothing;

-- 4. Insert exercise-muscle links for the catalogue exercises that exist, with one primary at most.
select md5('catalogue:link:' || i.id::text || ':' || l.muscle_key)::uuid, i.id, m.id, l.role
  from _cat_link l
  join _cat_id i on i.key = l.exercise_key
  join exercises e on e.id = i.id and e.deleted_at is null
  join muscles m on m.key = l.muscle_key and m.deleted_at is null
 where not exists (select 1 from exercise_muscles x where x.exercise_id = i.id and x.muscle_id = m.id and x.deleted_at is null)
   and (l.role <> 'primary' or not exists (select 1 from exercise_muscles x where x.exercise_id = i.id and x.role = 'primary' and x.deleted_at is null))
on conflict do nothing;

commit;

-- 5. Check summary (one table). Every row should read OK.
with ids as (select i.id from (select coalesce(s.id, md5('catalogue:exercise:' || c.key)::uuid) as id from (values ('bench_press'), ('incline_bench_press'), ('decline_bench_press'), ('dumbbell_bench_press'), ('incline_dumbbell_press'), ('decline_dumbbell_press'), ('smith_machine_bench_press'), ('smith_machine_incline_press'), ('machine_chest_press'), ('dumbbell_fly'), ('incline_dumbbell_fly'), ('cable_crossover'), ('low_to_high_cable_fly'), ('high_to_low_cable_fly'), ('pec_deck_fly'), ('push_ups'), ('decline_push_ups'), ('chest_dips'), ('resistance_band_chest_press'), ('pull_ups'), ('chin_ups'), ('neutral_grip_pull_ups'), ('assisted_pull_ups'), ('lat_pulldown'), ('close_grip_lat_pulldown'), ('underhand_lat_pulldown'), ('straight_arm_pulldown'), ('barbell_row'), ('pendlay_row'), ('underhand_barbell_row'), ('t_bar_row'), ('seated_cable_row'), ('wide_grip_seated_cable_row'), ('machine_row'), ('single_arm_dumbbell_row'), ('chest_supported_dumbbell_row'), ('single_arm_cable_row'), ('inverted_row'), ('resistance_band_row'), ('dumbbell_pullover'), ('barbell_shrug'), ('dumbbell_shrug'), ('face_pull'), ('band_pull_apart'), ('rack_pull'), ('back_extension'), ('superman'), ('overhead_press'), ('dumbbell_shoulder_press'), ('arnold_press'), ('machine_shoulder_press'), ('smith_machine_shoulder_press'), ('kettlebell_press'), ('pike_push_ups'), ('lateral_raise'), ('cable_lateral_raise'), ('resistance_band_lateral_raise'), ('front_raise'), ('cable_front_raise'), ('reverse_dumbbell_fly'), ('reverse_pec_deck_fly'), ('cable_rear_delt_fly'), ('band_face_pull'), ('upright_row'), ('barbell_curl'), ('ez_bar_curl'), ('dumbbell_curl'), ('hammer_curl'), ('preacher_curl'), ('dumbbell_preacher_curl'), ('incline_dumbbell_curl'), ('concentration_curl'), ('cable_curl'), ('cable_rope_hammer_curl'), ('reverse_curl'), ('resistance_band_curl'), ('cable_triceps_pushdown'), ('rope_triceps_pushdown'), ('reverse_grip_triceps_pushdown'), ('overhead_triceps_extension'), ('cable_overhead_triceps_extension'), ('skull_crushers'), ('close_grip_bench_press'), ('bench_dips'), ('triceps_dips'), ('diamond_push_ups'), ('triceps_kickback'), ('resistance_band_triceps_pushdown'), ('barbell_wrist_curl'), ('reverse_wrist_curl'), ('farmers_carry'), ('dead_hang'), ('barbell_squat'), ('front_squat'), ('goblet_squat'), ('smith_machine_squat'), ('bodyweight_squat'), ('leg_press'), ('leg_extension'), ('bulgarian_split_squat'), ('walking_lunges'), ('reverse_lunge'), ('step_ups'), ('sumo_squat'), ('sissy_squat'), ('romanian_deadlift'), ('dumbbell_romanian_deadlift'), ('stiff_leg_deadlift'), ('single_leg_romanian_deadlift'), ('conventional_deadlift'), ('sumo_deadlift'), ('kettlebell_deadlift'), ('kettlebell_swing'), ('barbell_hip_thrust'), ('glute_bridge'), ('cable_pull_through'), ('cable_glute_kickback'), ('lying_leg_curl'), ('seated_leg_curl'), ('nordic_hamstring_curl'), ('banded_lateral_walk'), ('cable_hip_abduction'), ('cable_hip_adduction'), ('standing_calf_raise'), ('seated_calf_raise'), ('leg_press_calf_raise'), ('single_leg_dumbbell_calf_raise'), ('bodyweight_calf_raise'), ('crunches'), ('weighted_crunches'), ('cable_crunch'), ('reverse_crunches'), ('hanging_leg_raise'), ('hanging_knee_raise'), ('lying_leg_raise'), ('plank'), ('side_plank'), ('russian_twists'), ('bicycle_crunch'), ('cable_woodchopper'), ('pallof_press'), ('dumbbell_side_bend'), ('dead_bug'), ('barbell_rollout')) c(key)
                               left join (values ('bench_press', 'a2aa281c-377b-7519-250e-f6a179ecb16a'::uuid), ('lat_pulldown', '17f2d66c-4c80-e1c5-a446-d445e3ff0e30'::uuid)) s(key, id) on s.key = c.key) i),
live as (select e.* from exercises e where e.deleted_at is null)
select check_name, value, expected, case when ok then 'OK' else 'CHECK' end as status from (
  select 1 as n, 'catalogue exercises present' as check_name, (select count(*) from live where id in (select id from ids))::text as value, '144 (fewer only if a same-named exercise was skipped)' as expected,
         (select count(*) from live where id in (select id from ids)) = 144 as ok
  union all select 2, 'all live exercises', (select count(*) from live)::text, '>= 144', (select count(*) from live) >= 144
  union all select 3, 'live exercise-muscle links (catalogue)', (select count(*) from exercise_muscles x where x.deleted_at is null and x.exercise_id in (select id from ids))::text, '419 (fewer only if links were skipped or you edited them)',
         (select count(*) from exercise_muscles x where x.deleted_at is null and x.exercise_id in (select id from ids)) = 419
  union all select 4, 'live exercises without a primary muscle', (select count(*) from live l where not exists (select 1 from exercise_muscles x where x.exercise_id = l.id and x.role = 'primary' and x.deleted_at is null))::text, '0 (custom ones may differ)',
         (select count(*) from live l where l.id in (select id from ids) and not exists (select 1 from exercise_muscles x where x.exercise_id = l.id and x.role = 'primary' and x.deleted_at is null)) = 0
  union all select 5, 'exercises with more than one primary', (select count(*) from (select exercise_id from exercise_muscles where role = 'primary' and deleted_at is null group by exercise_id having count(*) > 1) t)::text, '0',
         not exists (select 1 from exercise_muscles where role = 'primary' and deleted_at is null group by exercise_id having count(*) > 1)
  union all select 6, 'catalogue exercises with NULL category', (select count(*) from live where id in (select id from ids) and category is null)::text, '0', not exists (select 1 from live where id in (select id from ids) and category is null)
  union all select 7, 'catalogue exercises with NULL equipment', (select count(*) from live where id in (select id from ids) and equipment_id is null)::text, '0', not exists (select 1 from live where id in (select id from ids) and equipment_id is null)
  union all select 8, 'duplicate live names (any case)', (select count(*) from (select lower(name) from live group by 1 having count(*) > 1) t)::text, '0', not exists (select 1 from live group by lower(name) having count(*) > 1)
  union all select 9, 'bench press / lat pulldown ids kept', (select count(*) from live where id in ('a2aa281c-377b-7519-250e-f6a179ecb16a', '17f2d66c-4c80-e1c5-a446-d445e3ff0e30'))::text, '2', (select count(*) from live where id in ('a2aa281c-377b-7519-250e-f6a179ecb16a', '17f2d66c-4c80-e1c5-a446-d445e3ff0e30')) = 2
  union all select 10, 'links pointing at missing exercise/muscle', (select count(*) from exercise_muscles x where x.deleted_at is null and (not exists (select 1 from exercises e where e.id = x.exercise_id) or not exists (select 1 from muscles m where m.id = x.muscle_id)))::text, '0',
         not exists (select 1 from exercise_muscles x where x.deleted_at is null and (not exists (select 1 from exercises e where e.id = x.exercise_id) or not exists (select 1 from muscles m where m.id = x.muscle_id)))
) t order by n;
